// Embeds assets/profile-small.png (the 144px round profile picture) into src/offline/profile-image.ts as a data: URI.
// The offline page is a single file and its Content-Security-Policy only allows embedded images (img-src data:).
// To change the picture: replace assets/profile.png (README, 320px) and assets/profile-small.png (page, 144px), then run `npm run profile`.
const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
const png = fs.readFileSync(path.join(root, 'assets', 'profile-small.png'));
const ts =
  '// Generated by `npm run profile` from assets/profile-small.png: the page is one file and its security policy only allows embedded (data:) images.\n' +
  `export const PROFILE_IMAGE = "data:image/png;base64,${png.toString('base64')}";\n`;
fs.writeFileSync(path.join(root, 'src', 'offline', 'profile-image.ts'), ts);
console.log(`src/offline/profile-image.ts written (${png.length} bytes of image)`);
